static inline float MODEL_TEMP_F_predict_one_f(const float* x) {
    float s = 0.0f;
    for (int t = 0; t < MODEL_TEMP_F_NUM_TREES; t++) {
        int node = MODEL_TEMP_F_tree_roots[t];
        while (!MODEL_TEMP_F_nodes[node].is_leaf) {
            const MODEL_TEMP_F_node_t* n = &MODEL_TEMP_F_nodes[node];
            node = (x[n->feature] <= n->threshold) ? n->left : n->right;
        }
        s += MODEL_TEMP_F_nodes[node].value;
    }
    return s;
}

